# Test checkout. Astra wrote U6 and its fix, so it holds the subjective lane and native Opus
# (reviewer) holds the objective lane. Journal: scaffold/units/u6-audit-3-analyst.jsonl.
cd "C:/Users/mikes/WebstormProjects/test" || exit 9
timeout 3000 codex exec --json -C "C:/Users/mikes/WebstormProjects/test" --sandbox read-only --model gpt-6-astra -c 'model_reasoning_effort="high"' --output-last-message "u6-audit-3-analyst-last.md" "You hold the SUBJECTIVE lane (shape, naming, ergonomics, guide voice, design fit) of the third audit round of a unit your own engine wrote and fixed; judge it as a stranger would. Read ./../u6-audit-claims-3.md and rule on every claim 1 to 10 with CONFIRMED, REFUTED, or UNDECIDABLE and the deciding evidence (file:line or exact text), reading the working tree of this checkout (HEAD f49bc7f plus the uncommitted U6 diff), the cumulative diff at ./units/u6-diff.patch.txt, the reports at ./units/u6-report.md, ./units/u6-report-2.md, and ./units/u6-report-3.md, ./units/u6-report-4.md, the control logs ./units/u6-round4-*.log, the round 1 and 2 verdicts and lane reports under C:/Users/mikes/WebstormProjects/scaffold/.orkestrel/veneer/ (u6-audit-verdict.md, u6-audit-verdict-2.md, u6-audit-2-reviewer-report.md, u6-audit-2-analyst-report.md), the design at u6-design-planner-report.md and u6-design-verdict.md there, and the rules under C:/Users/mikes/WebstormProjects/scaffold/AGENTS.md and .claude/rules/. Run no command that writes. Add extra findings no claim names, numbered from 11, with sites. End with one terminal line: Verdict: accept, or Verdict: fix round with the claims that force it." < /dev/null > "u6-audit-3-analyst.jsonl" 2> "u6-audit-3-analyst.err"
echo "exit=$?" >> "u6-audit-3-analyst.err"
